"""Lidar range noise (P4) and beam dropout (P8) — docs/06 §3.4.

``r' = clip(r + N(0, P4²), range_min, range_max)``; then each beam independently becomes ``+inf``
(no return) with probability P8. The same functions run in kinematic2d and in the ROS
``sensor_perturber`` node, so both simulators perturb scans identically (docs/10 §7.1).

Design rules (shared with the ROS package, hence NumPy-only and vendorable):

* Pure: inputs are never modified; a new ``float64`` array of the same shape is returned.
* Seeded: randomness comes only from the caller's generator — the run's ``sensor`` stream
  (``core.seeding.SENSOR``, docs/21 §3) — so replays are identical.
* Parameter-independent stream use: one draw per beam on every call, even when ``std == 0`` or
  ``p == 0``, so changing P4/P8 never shifts the random numbers consumed by later models.
* Beams without a return (``+inf``) or invalid (``nan``) stay as they are: noise must not turn
  "no return" into a phantom obstacle at ``range_max``.
"""

from __future__ import annotations

import math

import numpy as np
import numpy.typing as npt

__all__ = ["apply_dropout", "apply_lidar_noise"]

FloatArray = npt.NDArray[np.float64]


def apply_lidar_noise(
    ranges: npt.ArrayLike,
    std: float,
    rng: np.random.Generator,
    r_min: float,
    r_max: float,
) -> FloatArray:
    """Add zero-mean Gaussian range noise and clip to the sensor limits (P4).

    Args:
        ranges: Measured ranges [m]; any shape. Non-finite entries are passed through.
        std: Noise standard deviation P4 [m], ``>= 0``.
        rng: The run's ``sensor`` stream.
        r_min: Sensor minimum range [m], ``>= 0``.
        r_max: Sensor maximum range [m], ``> r_min``.

    Returns:
        Noisy ranges [m] as a new ``float64`` array.

    Raises:
        ValueError: If ``std`` is negative or not finite, or the range limits are invalid.
    """
    if not (math.isfinite(std) and std >= 0.0):
        msg = f"noise std must be finite and >= 0, got {std}"
        raise ValueError(msg)
    if not (math.isfinite(r_min) and math.isfinite(r_max) and 0.0 <= r_min < r_max):
        msg = f"need 0 <= r_min < r_max (finite), got r_min={r_min}, r_max={r_max}"
        raise ValueError(msg)
    values = np.array(ranges, dtype=np.float64)
    noise = rng.normal(0.0, std, size=values.shape)
    finite = np.isfinite(values)
    values[finite] = np.clip(values[finite] + noise[finite], r_min, r_max)
    return values


def apply_dropout(ranges: npt.ArrayLike, p: float, rng: np.random.Generator) -> FloatArray:
    """Drop each beam independently with probability ``p`` (P8); dropped beams read ``+inf``.

    Args:
        ranges: Ranges [m]; any shape.
        p: Dropout probability P8 in ``[0, 1]``.
        rng: The run's ``sensor`` stream.

    Returns:
        Ranges with dropped beams set to ``+inf``, as a new ``float64`` array.

    Raises:
        ValueError: If ``p`` is outside ``[0, 1]``.
    """
    if not 0.0 <= p <= 1.0:  # also rejects nan
        msg = f"dropout probability must be in [0, 1], got {p}"
        raise ValueError(msg)
    values = np.array(ranges, dtype=np.float64)
    values[rng.random(size=values.shape) < p] = np.inf
    return values
